import 'package:fluent_query_builder/fluent_query_builder.dart';

void main() {
  final pgsqlCom = DBConnectionInfo(
    host: 'localhost',
    database: 'banco_teste',
    driver: ConnectionDriver.pgsql,
    port: 5432,
    username: 'user',
    password: 'pass',
  );

  DbLayer().connect(pgsqlCom).then((db) async {
    final result = await db.select().from('usuarios').getAsMap();
    print(result);
  });
}
